template<typename T, typename... Ts>
void createAndProcess(Ts&&... params)
{
  // Which one is correct? The template author can't know.

  // Option 1: Use parentheses
  T localObject1(std::forward<Ts>(params)...);
  // This would call std::vector<int>(10, 20) -> 10 elements

  // Option 2: Use braces
  T localObject2{std::forward<Ts>(params)...};
  // This would call std::vector<int>{10, 20} -> 2 elements

  // A choice must be made, and it will be wrong for some use cases.
}
